import Foundation
import Testing
@testable import TimetableCore

// The import eval harness (PHASE9_PLAN decision 7): every fixture in `Tests/Fixtures/import/` (generated by
// scripts/import-fixtures.py) is parsed and scored. The report is printed; set IMPORT_EVAL_REPORT=<path> to also
// write it as Markdown (docs/eval/IMPORT_EVAL.md quotes it). The thresholds below are regression guards set just
// under the measured numbers, not targets.

struct ImportFixture: Decodable {
    struct Options: Decodable {
        var knownSubjects: [String]?
        var enabledFields: [String]?
    }

    struct Period: Decodable {
        var number: Int
        var start: String
        var end: String
    }

    struct Lesson: Decodable {
        var day: Int
        var period: Int
        var span: Int
        var subject: String
        var room: String?
        var teacher: String?
        var lessonType: String?
        var notes: String?
        var weeks: [Int]?
    }

    struct Expected: Decodable {
        var orientation: String
        var days: [Int]
        var periods: [Period]
        var checkTimes: Bool
        var weekCycleLength: Int?
        var lessons: [Lesson]
    }

    var id: String
    var description: String
    var language: String
    var mode: String
    var layout: String
    var options: Options?
    var table: RecognizedTable
    var expected: Expected

    var parserOptions: ImportParserOptions {
        var result = ImportParserOptions()
        if let known = options?.knownSubjects { result.knownSubjects = known }
        if let fields = options?.enabledFields { result.enabledFields = Set(fields.map(LessonField.init(rawValue:))) }
        return result
    }

    static let directory: URL = {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<3 { url.deleteLastPathComponent() } // Import/ → TimetableCoreTests/ → Tests/
        return url.appendingPathComponent("Fixtures/import")
    }()

    static func all() throws -> [ImportFixture] {
        let files = try FileManager.default.contentsOfDirectory(atPath: directory.path).filter { $0.hasSuffix(".json") }.sorted()
        return try files.map { try JSONDecoder().decode(ImportFixture.self, from: Data(contentsOf: directory.appendingPathComponent($0))) }
    }
}

/// Scores of one fixture.
struct ImportScore {
    static let fields = ["subject", "room", "teacher", "lessonType", "span"]

    var id: String
    var mode: String
    var language: String
    var structureChecks: [String: Bool] = [:]
    var expectedLessons = 0
    var matchedLessons = 0
    var spuriousLessons = 0
    var exact: [String: Int] = [:]
    var fuzzy: [String: Int] = [:]
    /// (lesson wrong, flagged for review, confidence) for every matched lesson.
    var calibration: [(wrong: Bool, flagged: Bool, confidence: Double)] = []
    var mismatches: [String] = []

    var structureExact: Bool { structureChecks.values.allSatisfy { $0 } }
    var lessonsAllCorrect: Bool { matchedLessons == expectedLessons && spuriousLessons == 0 && !calibration.contains { $0.wrong } }

    init(_ fixture: ImportFixture, _ candidate: ImportCandidate) {
        id = fixture.id
        mode = fixture.mode
        language = fixture.language
        let expected = fixture.expected
        structureChecks["orientation"] = candidate.orientation.rawValue == expected.orientation
        structureChecks["days"] = candidate.days.map(\.rawValue) == expected.days
        structureChecks["periodNumbers"] = candidate.periods.map(\.number) == expected.periods.map(\.number)
        if expected.checkTimes {
            structureChecks["periodTimes"] = candidate.periods.map { [$0.start.isoString, $0.end.isoString] }
                == expected.periods.map { [$0.start, $0.end] }
        }
        structureChecks["weekCycle"] = candidate.weekCycleLength == expected.weekCycleLength
        structureChecks["lessonCount"] = candidate.lessons.count == expected.lessons.count

        expectedLessons = expected.lessons.count
        var unmatched = candidate.lessons
        for truth in expected.lessons {
            let weeks = truth.weeks.map(Set.init)
            guard let index = unmatched.firstIndex(where: {
                $0.day.rawValue == truth.day && $0.period == truth.period && $0.cycleWeeks == weeks
            }) else {
                calibration.append((true, false, 0)) // missing lesson: wrong and not flagged
                mismatches.append("missing: \(truth.subject) day \(truth.day) period \(truth.period)")
                continue
            }
            let lesson = unmatched.remove(at: index)
            matchedLessons += 1
            let pairs: [(String, String?, String?)] = [
                ("subject", truth.subject, lesson.subject), ("room", truth.room, lesson.room),
                ("teacher", truth.teacher, lesson.teacher), ("lessonType", truth.lessonType, lesson.lessonType?.rawValue),
                ("span", String(truth.span), String(lesson.span)),
            ] + (truth.notes.map { [("notes", $0, lesson.notes)] } ?? [])
            var wrong = false
            for (field, want, got) in pairs {
                if want == got { exact[field, default: 0] += 1 } else { wrong = true; mismatches.append("\(field): \(want ?? "nil") ≠ \(got ?? "nil")") }
                if want.map(ImportText.fold) == got.map(ImportText.fold) { fuzzy[field, default: 0] += 1 }
            }
            calibration.append((wrong, lesson.needsReview, lesson.confidence))
        }
        spuriousLessons = unmatched.count
    }
}

enum ImportEvalReport {
    static func percent(_ part: Int, _ whole: Int) -> String {
        whole == 0 ? "n/a" : String(format: "%.1f%%", 100 * Double(part) / Double(whole))
    }

    static func markdown(_ scores: [ImportScore]) -> String {
        var out: [String] = []
        let total = scores.map(\.expectedLessons).reduce(0, +)
        out.append("| Metric | Value |")
        out.append("|---|---|")
        out.append("| Fixtures | \(scores.count) (\(scores.filter { $0.mode == "cells" }.count) table cells, \(scores.filter { $0.mode == "lines" }.count) loose lines) |")
        out.append("| Structure exact (all checks) | \(scores.filter(\.structureExact).count) / \(scores.count) |")
        for check in ["orientation", "days", "periodNumbers", "periodTimes", "weekCycle", "lessonCount"] {
            let applicable = scores.filter { $0.structureChecks[check] != nil }
            out.append("| Structure: \(check) | \(applicable.filter { $0.structureChecks[check]! }.count) / \(applicable.count) |")
        }
        out.append("| Fixtures with every lesson fully correct | \(scores.filter(\.lessonsAllCorrect).count) / \(scores.count) |")
        out.append("| Lessons expected / found at the right slot | \(total) / \(scores.map(\.matchedLessons).reduce(0, +)) |")
        out.append("| Spurious lessons (no expected lesson at that slot) | \(scores.map(\.spuriousLessons).reduce(0, +)) |")
        for field in ImportScore.fields {
            let exact = scores.map { $0.exact[field] ?? 0 }.reduce(0, +)
            let fuzzy = scores.map { $0.fuzzy[field] ?? 0 }.reduce(0, +)
            out.append("| Field \(field): exact / folded | \(percent(exact, total)) / \(percent(fuzzy, total)) |")
        }
        let all = scores.flatMap(\.calibration)
        let wrong = all.filter(\.wrong), right = all.filter { !$0.wrong }
        let flagged = all.filter(\.flagged)
        let wrongFlagged = wrong.filter(\.flagged).count
        out.append("| Lessons with any wrong field (incl. missing) | \(wrong.count) / \(all.count) |")
        out.append("| Calibration: wrong lessons flagged for review (recall) | \(wrongFlagged) / \(wrong.count) (\(percent(wrongFlagged, wrong.count))) |")
        out.append("| Calibration: flagged lessons that are wrong (precision) | \(wrongFlagged) / \(flagged.count) (\(percent(wrongFlagged, flagged.count))) |")
        out.append("| Calibration: correct lessons not flagged | \(right.filter { !$0.flagged }.count) / \(right.count) |")
        let mean = { (xs: [(wrong: Bool, flagged: Bool, confidence: Double)]) in
            xs.isEmpty ? 0 : xs.map(\.confidence).reduce(0, +) / Double(xs.count)
        }
        out.append(String(format: "| Mean confidence: correct / wrong (found) lessons | %.2f / %.2f |", mean(right), mean(wrong.filter { $0.confidence > 0 })))
        out.append("")
        out.append("| Fixture | Lang | Input | Structure | Lessons right / expected | Spurious | Wrong but not flagged |")
        out.append("|---|---|---|---|---|---|---|")
        for score in scores {
            let failed = score.structureChecks.filter { !$0.value }.keys.sorted()
            let right = score.calibration.filter { !$0.wrong }.count
            let silent = score.calibration.filter { $0.wrong && !$0.flagged }.count
            out.append("| \(score.id) | \(score.language) | \(score.mode) | \(failed.isEmpty ? "ok" : "fails: " + failed.joined(separator: ", ")) | \(right) / \(score.expectedLessons) | \(score.spuriousLessons) | \(silent) |")
        }
        return out.joined(separator: "\n")
    }
}

@Suite("Import eval harness")
struct ImportEvalTests {
    @Test func fixturesCoverTheBrief() throws {
        let fixtures = try ImportFixture.all()
        #expect(fixtures.count >= 30)
        let languages = Set(fixtures.map { String($0.language.prefix(2)) })
        #expect(languages.isSuperset(of: ["en", "sk", "cs", "pl", "hu", "ro", "de", "fr", "uk", "sr", "ja", "zh"]))
        #expect(fixtures.contains { $0.layout == "columns" })
        #expect(fixtures.contains { $0.mode == "lines" })
        #expect(fixtures.contains { $0.expected.weekCycleLength == 2 })
        #expect(fixtures.contains { $0.id == "sk-asc-human" })
    }

    /// The human's aSc example must come out exactly, as table cells and transposed.
    @Test(arguments: ["sk-asc-human", "sk-asc-transposed"])
    func humanExampleIsExact(_ id: String) throws {
        let fixture = try #require(try ImportFixture.all().first { $0.id == id })
        let candidate = TimetableImportParser.parse(fixture.table, options: fixture.parserOptions)
        let score = ImportScore(fixture, candidate)
        #expect(score.structureExact, "\(score.structureChecks)")
        #expect(score.lessonsAllCorrect, "\(score.mismatches)")
        #expect(candidate.periods.map(\.start.isoString) == ["07:00", "07:50", "08:40", "09:30", "10:20", "11:10", "12:00",
                                                             "12:50", "13:50", "14:40", "15:30", "16:20", "17:10"])
        #expect(candidate.lessons.filter(\.needsReview).isEmpty)
    }

    @Test func neverInventsLessonsAndIsDeterministic() throws {
        for fixture in try ImportFixture.all() {
            let candidate = TimetableImportParser.parse(fixture.table, options: fixture.parserOptions)
            let texts = Set(fixture.table.gridCells.map(\.text))
            for lesson in candidate.lessons {
                #expect(texts.contains(lesson.sourceText), "\(fixture.id): lesson \(lesson.subject) not from an input cell")
                #expect(!lesson.subject.isEmpty)
                #expect(lesson.sourceText.contains(lesson.subject) || lesson.alternatives.contains { $0.field == .subject }
                        || ImportText.fold(lesson.sourceText).contains(ImportText.fold(lesson.subject)),
                        "\(fixture.id): subject \(lesson.subject) not in \(lesson.sourceText)")
            }
            #expect(TimetableImportParser.parse(fixture.table, options: fixture.parserOptions) == candidate)
            // Every candidate with lessons turns into a valid share payload.
            if !candidate.lessons.isEmpty {
                #expect(throws: Never.self) {
                    try ImportPayloadBuilder.payload(from: candidate, name: fixture.id, bellScheduleName: "Bells")
                }
            }
        }
    }

    @Test func metrics() throws {
        let fixtures = try ImportFixture.all()
        let scores = fixtures.map { ImportScore($0, TimetableImportParser.parse($0.table, options: $0.parserOptions)) }
        let report = ImportEvalReport.markdown(scores)
        print(report)
        // IMPORT_EVAL_DEBUG=<fixture id> prints what the parser made of one fixture.
        if let id = ProcessInfo.processInfo.environment["IMPORT_EVAL_DEBUG"], let fixture = fixtures.first(where: { $0.id == id }) {
            let candidate = TimetableImportParser.parse(fixture.table, options: fixture.parserOptions)
            for cell in fixture.table.gridCells { print("CELL r\(cell.row) c\(cell.column) s\(cell.columnSpan) \(cell.text.debugDescription)") }
            print("PERIODS", candidate.periods.map { "\($0.number) \($0.start)-\($0.end) \($0.timeSource)" })
            for lesson in candidate.lessons {
                print("GOT", lesson.day, lesson.period, lesson.span, lesson.cycleWeeks ?? [], lesson.subject, lesson.room ?? "-",
                      lesson.teacher ?? "-", lesson.lessonType?.rawValue ?? "-", lesson.notes ?? "-", lesson.reasons.sorted(),
                      String(format: "%.2f", lesson.confidence))
            }
            print("MISMATCH", ImportScore(fixture, candidate).mismatches)
            for lesson in fixture.expected.lessons {
                print("WANT", lesson.day, lesson.period, lesson.span, lesson.weeks ?? [], lesson.subject, lesson.room ?? "-",
                      lesson.teacher ?? "-", lesson.lessonType ?? "-")
            }
        }
        if let path = ProcessInfo.processInfo.environment["IMPORT_EVAL_REPORT"] {
            try report.write(toFile: path, atomically: true, encoding: .utf8)
        }
        let total = scores.map(\.expectedLessons).reduce(0, +)
        let subjects = scores.map { $0.exact["subject"] ?? 0 }.reduce(0, +)
        let all = scores.flatMap(\.calibration)
        // Measured 2026-11-03: structure 40/40, subject 96.2 %, recall 5/10 (docs/eval/IMPORT_EVAL.md).
        #expect(Double(scores.filter(\.structureExact).count) / Double(scores.count) >= 0.9)
        #expect(Double(subjects) / Double(total) >= 0.9)
        #expect(Double(all.filter { $0.wrong && $0.flagged }.count) / Double(max(1, all.filter(\.wrong).count)) >= 0.4)
    }
}
